import{_ as e,o as i,c as t,a2 as s}from"./chunks/framework.iXqqCa-C.js";const l="/images/misskey-clips.webp",u=JSON.parse('{"title":"便签与收藏","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/clips-favorites.md","filePath":"guide/misskey/clips-favorites.md","lastUpdated":1793501934000}'),r={name:"guide/misskey/clips-favorites.md"};function o(p,a,n,c,d,_){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="便签与收藏" tabindex="-1">便签与收藏 <a class="header-anchor" href="#便签与收藏" aria-label="Permalink to &quot;便签与收藏&quot;">​</a></h1><p>便签和收藏都用来保存帖子：便签可以分类并公开，收藏只有自己可见。</p><h2 id="便签" tabindex="-1">便签 <a class="header-anchor" href="#便签" aria-label="Permalink to &quot;便签&quot;">​</a></h2><p>便签（Clip）是自建的帖子合集：</p><ul><li>通过侧栏「便签」创建合集，例如「同人图存档」「灵感记录」，可填写名称和描述。</li><li>在帖子菜单中选择「便签」，把帖子加入合集。</li><li>便签可以设为<strong>公开</strong>并分享链接，也可以保持私有。</li><li>可创建的便签数量和每个便签可收录的帖子数由服务器策略决定，上限为 0 时无法新建便签。</li></ul><p><img src="'+l+'" alt="便签"></p><h2 id="收藏" tabindex="-1">收藏 <a class="header-anchor" href="#收藏" aria-label="Permalink to &quot;收藏&quot;">​</a></h2><p>收藏（Favorites）是不分类的收藏夹：</p><ul><li>在帖子菜单中选择「收藏」，帖子进入「收藏」列表，再次选择可取消。</li><li>收藏列表只有自己可见，适合标记以后再看的帖子。</li></ul><p>需要按主题整理或分享给别人时用便签，只想留个记号时用收藏。</p>',10)])])}const h=e(r,[["render",o]]);export{u as __pageData,h as default};
